ALTER TYPE "public"."march_order" ADD VALUE 'found';--> statement-breakpoint
ALTER TABLE "fief_marches" DROP CONSTRAINT "fief_marches_order_terms";--> statement-breakpoint
ALTER TABLE "fief_marches" ADD COLUMN "founding_name" text;--> statement-breakpoint
CREATE UNIQUE INDEX "fief_marches_founding_plot_unique" ON "fief_marches" USING btree ("province","plot") WHERE "fief_marches"."founding_name" IS NOT NULL AND "fief_marches"."recalled_at" IS NULL;--> statement-breakpoint
ALTER TABLE "fief_marches" ADD CONSTRAINT "fief_marches_order_terms" CHECK (("fief_marches"."march_order"::text = 'forage' AND "fief_marches"."stay_hours" >= 1 AND "fief_marches"."camp_tier" IS NULL AND "fief_marches"."camp_strength" IS NULL AND NOT "fief_marches"."fought" AND "fief_marches"."founding_name" IS NULL) OR ("fief_marches"."march_order"::text = 'attack' AND "fief_marches"."stay_hours" = 0 AND "fief_marches"."camp_tier" IS NOT NULL AND "fief_marches"."camp_tier" BETWEEN 1 AND 3 AND "fief_marches"."camp_strength" IS NOT NULL AND "fief_marches"."camp_strength" >= 0 AND "fief_marches"."founding_name" IS NULL) OR ("fief_marches"."march_order"::text = 'found' AND "fief_marches"."stay_hours" = 0 AND "fief_marches"."camp_tier" IS NULL AND "fief_marches"."camp_strength" IS NULL AND NOT "fief_marches"."fought" AND "fief_marches"."founding_name" IS NOT NULL AND "fief_marches"."settler_count" = 1 AND "fief_marches"."infantry_count" = 0 AND "fief_marches"."cavalry_count" = 0));